import fs from "node:fs";
import path from "node:path";

/**
 * Normalizes all symlinks inside `.next/node_modules` (generated by Turbopack)
 * into portable relative symlinks using `path.relative()`.
 *
 * Prevents broken module resolution when deploying pre-built artifacts across
 * directories or heterogeneous OS nodes.
 */
export function normalizeNextSymlinks(baseDir = process.cwd()) {
  const nextNodeModules = path.join(baseDir, ".next", "node_modules");
  if (!fs.existsSync(nextNodeModules)) {
    return;
  }

  const realNodeModules = path.join(baseDir, "node_modules");

  function walk(currentDir) {
    const entries = fs.readdirSync(currentDir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      if (entry.isSymbolicLink()) {
        let rawTarget = fs.readlinkSync(fullPath);
        // If target was an absolute path from the build host, map it to the target node_modules
        let absoluteTarget;
        // Check for Windows path (C:\ or D:/) or POSIX path or Git-bash style (/d/proj/...)
        const gitBashMatch = rawTarget.match(/^\/[a-zA-Z]\/.*[\\/]node_modules[\\/](.*)$/);
        if (gitBashMatch) {
          absoluteTarget = path.join(realNodeModules, gitBashMatch[1]);
        } else if (path.isAbsolute(rawTarget) || /^[a-zA-Z]:[\\/]/.test(rawTarget)) {
          const parts = rawTarget.split(/[\\/]node_modules[\\/]/);
          if (parts.length > 1) {
            absoluteTarget = path.join(realNodeModules, parts.slice(1).join(path.sep));
          } else {
            absoluteTarget = rawTarget;
          }
        } else {
          absoluteTarget = path.resolve(currentDir, rawTarget);
        }

        // Standard cross-platform relative path calculation
        const relativeTarget = path.relative(currentDir, absoluteTarget);

        fs.unlinkSync(fullPath);
        fs.symlinkSync(relativeTarget, fullPath);
      } else if (entry.isDirectory()) {
        walk(fullPath);
      }
    }
  }

  walk(nextNodeModules);
}

normalizeNextSymlinks();
console.log("Normalized symlinks in .next/node_modules successfully.");
